function validate([n, edges, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is between 1 and 10^4.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 edges.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each edge is [u, v, w].';
    const [u, v, w] = edge;
    if (u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints are between 0 and n - 1.';
    if (w < 1 || w > 26) return 'Edge weights are between 1 and 26.';
    const ru = find(u), rv = find(v);
    if (ru === rv) return 'edges must form a tree (no cycles).';
    parent[ru] = rv;
  }
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 20000) return 'queries has 1 to 2 * 10^4 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2 || !query.every(x => Number.isInteger(x) && x >= 0 && x < n)) return 'Each query is [a, b] with nodes between 0 and n - 1.';
  }
  return null;
}

