function minOperationsQueries(n, edges, queries) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    graph[u].push([v, w]);
    graph[v].push([u, w]);
  }

  const LOG = Math.max(1, Math.ceil(Math.log2(n)));
  const up = Array.from({ length: LOG }, () => new Array(n).fill(0));
  const depth = new Array(n).fill(0);
  const count = Array.from({ length: n }, () => new Array(27).fill(0));
  const visited = new Array(n).fill(false);
  const queue = [0];
  visited[0] = true;

  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    for (const [next, w] of graph[node]) {
      if (visited[next]) continue;
      visited[next] = true;
      up[0][next] = node;
      depth[next] = depth[node] + 1;
      count[next] = count[node].slice();
      count[next][w]++;
      queue.push(next);
    }
  }

  for (let j = 1; j < LOG; j++) {
    for (let v = 0; v < n; v++) {
      up[j][v] = up[j - 1][up[j - 1][v]];
    }
  }

  const lca = (a, b) => {
    if (depth[a] < depth[b]) [a, b] = [b, a];
    for (let j = LOG - 1; j >= 0; j--) {
      if (depth[a] - (1 << j) >= depth[b]) a = up[j][a];
    }
    if (a === b) return a;
    for (let j = LOG - 1; j >= 0; j--) {
      if (up[j][a] !== up[j][b]) {
        a = up[j][a];
        b = up[j][b];
      }
    }
    return up[0][a];
  };

  return queries.map(([a, b]) => {
    const ancestor = lca(a, b);
    const length = depth[a] + depth[b] - 2 * depth[ancestor];
    let most = 0;
    for (let w = 1; w <= 26; w++) {
      most = Math.max(most, count[a][w] + count[b][w] - 2 * count[ancestor][w]);
    }
    return length - most;
  });
}

