function minOperationsQueries(n, edges, queries) {
  // Walk the actual path for every query: search from a, remembering how each node was reached.
  const neighbours = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) { neighbours[u].push([v, w]); neighbours[v].push([u, w]); }
  return queries.map(([a, b]) => {
    const cameFrom = new Array(n).fill(null);
    cameFrom[a] = [-1, 0];
    const stack = [a];
    while (stack.length) {
      const x = stack.pop();
      for (const [y, w] of neighbours[x]) if (cameFrom[y] === null) { cameFrom[y] = [x, w]; stack.push(y); }
    }
    const weights = [];
    for (let x = b; x !== a; x = cameFrom[x][0]) weights.push(cameFrom[x][1]);
    let keep = 0;
    for (const w of weights) keep = Math.max(keep, weights.filter(other => other === w).length);
    return weights.length - keep;
  });
}

